const tz = 'America/Montevideo';
const now = DateTime.now().setZone(tz); // domingo (día de ejecución)
const lastSat = now.minus({ days: 1 }); // sábado de referencia
const firstOfMonth = lastSat.startOf('month');

// Primer sábado del mes (weekday 6 = sábado en Luxon)
const dow = firstOfMonth.weekday;
const daysToSat = ((6 - dow) % 7 + 7) % 7;
const firstSatOfMonth = firstOfMonth.plus({ days: daysToSat });

// Es semana puente si hoy es el primer domingo del mes Y el mes no empieza lunes
const esSemanaPuente =
  lastSat.hasSame(firstSatOfMonth, 'day') && firstOfMonth.weekday !== 1;

return [{ json: { esSemanaPuente } }];

